// k17 状態変化と密度
const dotGrid = (n: number, x0: number, y0: number, gap: number, perRow: number): DiagramElement[] => {
  const out: DiagramElement[] = [];
  for (let i = 0; i < n; i += 1) out.push(ci(x0 + (i % perRow) * gap, y0 + Math.floor(i / perRow) * gap, 5, undefined, C.blue, FILL.blue));
  return out;
};
