// k20 電解質と非電解質
const k20Boxes = (on: boolean): DiagramElement[] => {
  const names = ['A\n食塩水', 'B\n砂糖水', 'C\n塩化銅', 'D\nエタノール', 'E\n蒸留水'];
  const lit = [true, false, true, false, false];
  return names.flatMap((t, i) => [bx(8 + i * 60, 20, 54, 44, t, on && lit[i] ? C.green : C.gray, on && lit[i] ? FILL.green : FILL.gray, 10), ...(on ? [lb(35 + i * 60, 80, lit[i] ? '光る' : '光らない', 9, lit[i] ? C.green : C.gray, 'middle', true)] : [])]);
};
