// k24 原子モデル（銅の酸化）
const cuAtom = (x: number, y: number): DiagramElement => ci(x, y, 9, 'Cu', C.main, FILL.warm, 8);
const oAtom = (x: number, y: number): DiagramElement => ci(x, y, 8, 'O', C.blue, FILL.blue, 9);
const f24 = show([
  { note: '銅原子（Cu）8個と、酸素分子（O₂）3個を反応させます。銅と酸素から、酸化銅（CuO）ができます。',
    add: [...[30, 54, 78, 102].flatMap((x) => [cuAtom(x, 40), cuAtom(x, 64)]), ...[36, 64, 92].flatMap((y) => [oAtom(200, y), oAtom(218, y), ln(207, y, 211, y, C.ink, false, 2)]), lb(66, 24, '銅原子 8個', 10, C.main, 'middle', true), lb(209, 18, '酸素分子 3個', 10, C.blue, 'middle', true), ...m('銅原子8個と酸素分子3個')] },
  { note: '❓化学反応式は？ 酸素は原子2個の分子（O₂）、酸化銅は銅原子1個と酸素原子1個です。左右の原子の数をそろえると、2Cu＋O₂ → 2CuO です。(1)の答えです。',
    add: fresh(bx(10, 24, 300, 36, '2Cu ＋ O₂ → 2CuO', C.green, FILL.green, 16), row(72, '酸素分子1個（O原子2個）で CuO が2個できる', C.gray, FILL.gray, 11), ...m('(1) 2Cu＋O₂ → 2CuO', C.green, FILL.green)) },
  { note: '❓酸化銅は何個できる？ 酸素分子3個には、酸素原子が 3×2＝6個あります。CuO1個に酸素原子が1個必要なので、最大6個できます。銅原子は6個必要ですが、8個あるので足ります。(2)の答えです。',
    add: fresh(row(16, '酸素原子の数＝3個×2＝6個', C.blue, FILL.blue, 12, 26), row(48, 'CuO 1個に O原子 1個 → 最大6個', C.blue, FILL.blue, 12, 26), row(80, '銅原子は6個必要（8個あるので足りる）', C.gray, FILL.gray, 12, 26), ...m('(2) 6個', C.blue, FILL.blue)) },
  { note: '❓余るものは？ 6個の酸化銅をつくるのに、銅原子を6個使います。8−6＝2個の銅原子が余ります。酸素分子は、すべて使いきります。(3)の答えです。',
    add: fresh(...[30, 100, 170].flatMap((x) => [cuAtom(x, 44), oAtom(x + 18, 44), cuAtom(x, 74), oAtom(x + 18, 74)]), cuAtom(256, 59), cuAtom(282, 59), lb(100, 24, '酸化銅 6個', 10, C.green, 'middle', true), lb(269, 36, '余る', 10, C.red, 'middle', true), ...m('(3) 銅原子が2個余る', C.red, FILL.red)) },
  { note: '❓反応の前後で変わらないものは？ 原子の種類も、原子の数も変わりません。原子の数が変わらないので、全体の質量も変わりません。物質の種類は、銅と酸素から酸化銅にかわります。(4)の答えです。',
    add: fresh(bx(20, 16, 130, 28, '原子の種類：変わらない', C.green, FILL.green, 10), bx(170, 16, 130, 28, '原子の数：変わらない', C.green, FILL.green, 10), bx(20, 52, 130, 28, '全体の質量：変わらない', C.green, FILL.green, 10), bx(170, 52, 130, 28, '物質の種類：変わる', C.red, FILL.red, 10), ...m('(4) ア、イ、エ', C.green, FILL.green)) },
  { note: '原子の数を数えて確かめます。反応前は、銅原子8個と酸素原子6個で、合計14個。反応後は、酸化銅6個（銅6個・酸素6個）と、余った銅2個で、銅8個・酸素6個、合計14個です。',
    add: fresh(row(16, '反応前：Cu 8個・O 6個　合計 14個', C.gray, FILL.gray, 12), row(50, '反応後：Cu 6＋2個・O 6個　合計 14個', C.gray, FILL.gray, 12), ...m('原子の数が前後で同じ', C.green, FILL.green)) },
  { note: '確かめます。反応の前後で、原子は14個のままです。反応の量は化学反応式の比で決まり、少ないほう（酸素）に合わせて、できる量が決まります。',
    add: m('反応前後で原子は14個で同じ', C.green, FILL.green) },
], '答え：(1) 2Cu＋O₂ → 2CuO (2) 6個 (3) 銅原子が2個余る (4) ア、イ、エ');

